from __future__ import division, absolute_import, print_function,\
    unicode_literals

from builtins import object, super
from abc import ABCMeta, abstractmethod
from future import standard_library
from future.utils import with_metaclass
standard_library.install_aliases()


class CmdBuilder(with_metaclass(ABCMeta, object)):
    """Base class responsible for tcpdump command preparation. """
    # __metaclass__ = ABCMeta

    def __init__(self, tcpdump_path, display_filter, sudo, preferences=None, log_dir=None):
        self._log_dir = log_dir
        self._tcpdump = tcpdump_path
        self._display_filter = display_filter
        self._preferences = '-o {} '.format(
            ' -o '.join(preferences.split())) if preferences else ''
        print("#### sudo is {}".format(sudo))
        self._sudo = 'sudo ' if sudo else ''
        print("#### _sudo is {}".format(self._sudo))

    @abstractmethod
    def build(self):
        """ Abstract method to prepare command for tcpdump. """


class CapturingCmdBuilder(CmdBuilder):
    """ Class prepares tcpdump command, which allows to save packets into
     pcap files. """

    CMD = "{sudo}tcpdump -i {eth}  -s {snap} -w \'{log}\' {packets_option}" \
          "{duration_option}{split_option}{override_preferences}  \'{cfil}\'" \
          "> /dev/null 2> {log_dir}/{classname}_tcpdump_error_log & echo $!"

    def __init__(self, tcpdump_path, interface, capture_filter, pcap_file, snap, split, display_filter, preferences,
                 log_dir, duration, packets, sudo):
        super(CapturingCmdBuilder, self).__init__(tcpdump_path, display_filter, sudo, preferences, log_dir)
        self._capture_interface = interface.split()
        self._capture_filter = capture_filter
        self._pcap = pcap_file
        self._snap = snap
        self._split = split
        self._duration = '-G duration:{} '.format(duration) if duration else ''
        self._packets = '-c {} '.format(packets) if packets else ''

    def build(self):
        """ Builds tcpdump command. """
        capture_interfaces = ' -i '.join(self._capture_interface)
        return CapturingCmdBuilder.CMD.format(bin=self._tcpdump, eth=capture_interfaces, snap=self._snap,
                                              log=self._pcap, duration_option=self._duration,
                                              packets_option=self._packets, split_option=self._set_file_max_size(),
                                              override_preferences=self._preferences, cfil=self._capture_filter,
                                              log_dir=self._log_dir, classname='SavingPackets', sudo=self._sudo)

    def _set_file_max_size(self):
        return '' if not self._split else '-b filesize:{} '.format(self._split)


class CountingCmdBuilder(CmdBuilder):
    """ Class prepares tcpdump command, which allows to store packets as txt files."""

    CMD = "{sudo}tcpdump -i {eth} {override_preferences}{filter_option} \'{pfil}\' -l > "\
          "{log} 2>{log_dir}/{classname}_tshark_error_log & echo $!"

    def __init__(self, tcpdump_path, interface, packet_filter, log_file, display_filter, preferences, log_dir, sudo):
        super(CountingCmdBuilder, self).__init__(tcpdump_path, display_filter, sudo, preferences, log_dir)
        self._capture_interface = interface.split()
        self._packet_filter = packet_filter
        self._log_file = log_file

    def build(self):
        """ Builds tcpdump command. """
        capture_interfaces = ' -i '.join(self._capture_interface)
        return CountingCmdBuilder.CMD.format(bin=self._tcpdump, eth=capture_interfaces,
                                             override_preferences=self._preferences,
                                             filter_option=self._display_filter,
                                             pfil=self._packet_filter,
                                             log=self._log_file, log_dir=self._log_dir, classname='CountingPackets',
                                             sudo=self._sudo)


class ReadingCmdBuilder(CmdBuilder):
    """Class prepares tcpdump command, which allows to read pcap files and return packet content in text or xml form."""

    CMD = "{sudo}tcpdump -r \'{pcap}\' {filter_option} \'{pfil}\' -T {type}{decode}"

    FORMS = {'lines': 'text', 'text': 'text -V', 'pdml': 'pdml'}

    def __init__(self, tcpdump_path, packet_filter, pcap_path, output_type, display_filter, decode_as, sudo):
        super(ReadingCmdBuilder, self).__init__(tcpdump_path, display_filter, sudo)
        self._pcap = pcap_path
        self._packet_filter = packet_filter
        self._format = output_type
        self._decode = decode_as

    def build(self):
        """ Builds tcpdump command. """
        decode_as = ' -d {}'.format(self._decode) if self._decode else ''
        return ReadingCmdBuilder.CMD.format(bin=self._tcpdump, pcap=self._pcap, filter_option=self._display_filter,
                                            pfil=self._packet_filter, type=ReadingCmdBuilder.FORMS[self._format],
                                            decode=decode_as, sudo=self._sudo)
